package com.killstolevel;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;
import net.runelite.api.NPC;
import net.runelite.api.Skill;
import net.runelite.api.WorldType;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.NpcDespawned;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.NpcUtil;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * A plugin wired to a mocked client, plus the real overlay, so both the screenshot tool and the
 * overlay tests can drive it without running the game.
 */
final class SimulatedGame
{
	private static final int DESPAWN_LAG_TICKS = 6;

	final Client client = mock(Client.class);
	final NpcUtil npcUtil = mock(NpcUtil.class);
	final KillsToLevelConfig config = mock(KillsToLevelConfig.class);
	final KillsToLevelPlugin plugin = new KillsToLevelPlugin();
	final KillsToLevelOverlay overlay;

	private final Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
	private int npcIndex;

	SimulatedGame()
	{
		when(client.getSkillExperience(any(Skill.class)))
			.thenAnswer(inv -> xp.getOrDefault(inv.<Skill>getArgument(0), 0));
		when(client.getVarpValue(anyInt())).thenReturn(0);
		when(client.getWorldType()).thenReturn(EnumSet.noneOf(WorldType.class));
		when(config.sampleWindow()).thenReturn(20);
		when(config.useInGameGoal()).thenReturn(true);
		when(config.showHitpoints()).thenReturn(true);

		plugin.client = client;
		plugin.npcUtil = npcUtil;
		plugin.config = config;
		plugin.overlayManager = mock(OverlayManager.class);
		plugin.overlay = mock(KillsToLevelOverlay.class);

		xp.put(Skill.STRENGTH, 1000);
		xp.put(Skill.HITPOINTS, 5000);

		plugin.startUp();
		overlay = new KillsToLevelOverlay(plugin);
	}

	/** Kill goblins: 5 damage each, so 20 Strength XP and ~6 Hitpoints XP per kill. */
	SimulatedGame kills(int count)
	{
		return kills(count, 5, 20);
	}

	/** Kill monsters dealing {@code damage} a kill and paying {@code strengthXp} for it. */
	SimulatedGame kills(int count, int damage, int strengthXp)
	{
		tick(2);
		for (int i = 0; i < count; i++)
		{
			NPC npc = mock(NPC.class);
			when(npc.getIndex()).thenReturn(++npcIndex);
			when(npcUtil.isDying(npc)).thenReturn(true);

			xp.merge(Skill.STRENGTH, strengthXp, Integer::sum);
			xp.merge(Skill.HITPOINTS, 6, Integer::sum);

			HitsplatApplied hit = new HitsplatApplied();
			hit.setActor(npc);
			hit.setHitsplat(hitsplat(damage));
			plugin.onHitsplatApplied(hit);

			tick(DESPAWN_LAG_TICKS);
			plugin.onNpcDespawned(new NpcDespawned(npc));
			tick(1);
		}
		return this;
	}

	/**
	 * A kill whose XP registers too late for attribution: the corpse despawns and is credited, but
	 * no estimator is fed. The XP then arrives, to be measured into the NEXT kill's gain.
	 */
	SimulatedGame killWithLateXp(int damage, int strengthXp)
	{
		tick(2);
		NPC npc = mock(NPC.class);
		when(npc.getIndex()).thenReturn(++npcIndex);
		when(npcUtil.isDying(npc)).thenReturn(true);

		HitsplatApplied hit = new HitsplatApplied();
		hit.setActor(npc);
		hit.setHitsplat(hitsplat(damage));
		plugin.onHitsplatApplied(hit);

		tick(DESPAWN_LAG_TICKS);
		plugin.onNpcDespawned(new NpcDespawned(npc));
		xp.merge(Skill.STRENGTH, strengthXp, Integer::sum);
		tick(2);
		return this;
	}

	/** Grant XP with no hitsplat behind it — a lamp, a quest reward — landing between kills. */
	SimulatedGame lamp(Skill skill, int amount)
	{
		xp.merge(skill, amount, Integer::sum);
		tick(2);
		return this;
	}

	/** Move the session onto a Leagues-style world, where XP is multiplied. */
	SimulatedGame seasonalWorld()
	{
		when(client.getWorldType()).thenReturn(EnumSet.of(WorldType.SEASONAL));
		return this;
	}

	/** Change the sample window mid-session, as the config panel would. */
	SimulatedGame sampleWindow(int kills)
	{
		when(config.sampleWindow()).thenReturn(kills);
		ConfigChanged change = new ConfigChanged();
		change.setGroup(KillsToLevelConfig.GROUP);
		plugin.onConfigChanged(change);
		return this;
	}

	SimulatedGame hideHitpoints()
	{
		when(config.showHitpoints()).thenReturn(false);
		return this;
	}

	/** Land hits without completing any kill, to check overlay state before the first one lands. */
	SimulatedGame hits(int count)
	{
		tick(2);
		for (int i = 0; i < count; i++)
		{
			NPC npc = mock(NPC.class);
			when(npc.getIndex()).thenReturn(++npcIndex);

			xp.merge(Skill.STRENGTH, 20, Integer::sum);
			xp.merge(Skill.HITPOINTS, 6, Integer::sum);

			HitsplatApplied hit = new HitsplatApplied();
			hit.setActor(npc);
			hit.setHitsplat(hitsplat(5));
			plugin.onHitsplatApplied(hit);
		}
		return this;
	}

	SimulatedGame xpTarget(@SuppressWarnings("SameParameterValue") int varp, int goalXp)
	{
		when(client.getVarpValue(varp)).thenReturn(goalXp);
		return this;
	}

	private void tick(int times)
	{
		for (int i = 0; i < times; i++)
		{
			plugin.onGameTick(new GameTick());
		}
	}

	private static Hitsplat hitsplat(int amount)
	{
		return new Hitsplat()
		{
			@Override
			public int getHitsplatType()
			{
				return HitsplatID.DAMAGE_ME;
			}

			@Override
			public int getAmount()
			{
				return amount;
			}

			@Override
			public int getDisappearsOnGameCycle()
			{
				return 0;
			}
		};
	}

	/**
	 * Render the overlay and return its size, or null if it drew nothing. Rendered twice on
	 * purpose: {@code PanelComponent} sizes itself from the child dimensions measured during the
	 * previous pass, so a single render only ever reports the border.
	 */
	Dimension render(Graphics2D graphics)
	{
		overlay.render(graphics);
		return overlay.render(graphics);
	}

	BufferedImage renderToImage()
	{
		BufferedImage probe = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
		Graphics2D pg = probe.createGraphics();
		Dimension size = render(pg);
		pg.dispose();
		if (size == null || size.width <= 0 || size.height <= 0)
		{
			return null;
		}

		BufferedImage img = new BufferedImage(size.width, size.height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		render(g);
		g.dispose();
		return img;
	}

	/** The text rows the overlay actually put on screen, in order, as "left|right". */
	List<String> renderedLines()
	{
		// OverlayPanel empties the panel in a finally block once it has drawn, so the components
		// would be gone before we could read them. The overlay clears and rebuilds them itself at
		// the top of every render, so switching this off changes nothing about what is drawn.
		overlay.setClearChildren(false);

		BufferedImage probe = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = probe.createGraphics();
		render(g);
		g.dispose();

		List<String> lines = new ArrayList<>();
		for (LayoutableRenderableEntity child : overlay.getPanelComponent().getChildren())
		{
			String left = field(child, "left");
			String right = field(child, "right");
			String title = field(child, "text");
			if (title != null)
			{
				lines.add("title:" + title);
			}
			else
			{
				lines.add((left == null ? "" : left) + "|" + (right == null ? "" : right));
			}
		}
		return lines;
	}

	/**
	 * The colour the overlay drew a row's right-hand value in, so grey (measured but still being
	 * confirmed) can be told apart from solid (confident). Null if there is no such row.
	 */
	Color rightColorOf(String left)
	{
		overlay.setClearChildren(false);

		BufferedImage probe = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = probe.createGraphics();
		render(g);
		g.dispose();

		for (LayoutableRenderableEntity child : overlay.getPanelComponent().getChildren())
		{
			if (left.equals(field(child, "left")))
			{
				return (Color) rawField(child, "rightColor");
			}
		}
		return null;
	}

	/** Read a private field off a RuneLite component — they expose setters but no getters. */
	private static String field(Object target, String name)
	{
		Object value = rawField(target, name);
		return value == null ? null : value.toString();
	}

	private static Object rawField(Object target, String name)
	{
		try
		{
			Field f = target.getClass().getDeclaredField(name);
			f.setAccessible(true);
			return f.get(target);
		}
		catch (NoSuchFieldException e)
		{
			return null;
		}
		catch (IllegalAccessException e)
		{
			throw new AssertionError("cannot read " + name + " from " + target.getClass(), e);
		}
	}
}

package com.killstolevel;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.List;
import net.runelite.api.gameval.VarPlayerID;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Renders the real overlay against a mocked client and asserts on what it actually drew. The unit
 * tests cover the numbers; these cover the thing tests usually cannot — whether anything reaches
 * the screen, and what it says when it does.
 */
public class OverlayRenderTest
{
	@Test
	public void drawsNothingWithNoCombatAtAll()
	{
		SimulatedGame game = new SimulatedGame();
		assertNull("overlay must stay hidden until something trains a skill",
			game.renderToImage());
	}

	/**
	 * The overlay used to wait for the first kill to complete before showing anything — before
	 * that, nothing said which skill you were training. It now appears on the first hit whose xp
	 * registers, since that's the same signal a completed kill would have given, just earlier.
	 */
	@Test
	public void showsTheSkillOnTheFirstHitBeforeAnyKillCompletes()
	{
		List<String> lines = new SimulatedGame().hits(1).renderedLines();

		assertEquals("title:Kills to level", lines.get(0));
		assertTrue("a hit must show the skill it trained, before any kill: " + lines,
			lines.contains("Strength|Measuring"));
		assertTrue("and say it is measuring, since one kill has not even happened yet: " + lines,
			lines.stream().noneMatch(l -> l.matches("Strength\\|~?\\d+")));
	}

	/**
	 * Three kills is a real measurement — two would do — but not yet a confident one, so the number
	 * is shown greyed with a "~" rather than withheld. Waiting for five meant staring at a
	 * placeholder for the first minute of every session with no number to act on; the prefix is
	 * there because colour alone is easy to miss.
	 */
	@Test
	public void thinlyMeasuredSkillShowsATildedGreyNumber()
	{
		SimulatedGame game = new SimulatedGame().kills(3);
		List<String> lines = game.renderedLines();

		assertEquals("title:Kills to level", lines.get(0));
		assertTrue("three kills must produce a number, marked ~ while thin: " + lines,
			lines.stream().anyMatch(l -> l.matches("Strength\\|~\\d+")));
		assertEquals("and it must be greyed to say it is still being confirmed",
			Color.LIGHT_GRAY, game.rightColorOf("Strength"));
	}

	@Test
	public void confidentSkillShowsASolidNumber()
	{
		SimulatedGame game = new SimulatedGame().kills(9);

		assertTrue("nine kills is past the confidence threshold: " + game.renderedLines(),
			game.renderedLines().stream().anyMatch(l -> l.matches("Strength\\|\\d+")));
		assertTrue("a confident number must not carry the ~: " + game.renderedLines(),
			game.renderedLines().stream().noneMatch(l -> l.contains("|~")));
		assertEquals("a confident number must not be greyed",
			Color.WHITE, game.rightColorOf("Strength"));
	}

	@Test
	public void measuredShowsCountsAndDropsTheProgressLine()
	{
		List<String> lines = new SimulatedGame().kills(9).renderedLines();

		assertEquals("title:Kills to level", lines.get(0));
		assertTrue("strength should show a number: " + lines,
			lines.stream().anyMatch(l -> l.matches("Strength\\|\\d+")));
		assertTrue("no shared warm-up line — confidence is per-row, in the colour: " + lines,
			lines.stream().noneMatch(l -> l.contains("kills measured")));
	}

	@Test
	public void hidingHitpointsLeavesOnlyTheStyleSkill()
	{
		List<String> shown = new SimulatedGame().kills(9).renderedLines();
		assertTrue("hitpoints is listed by default: " + shown,
			shown.stream().anyMatch(l -> l.startsWith("Hitpoints|")));

		List<String> hidden = new SimulatedGame().hideHitpoints().kills(9).renderedLines();
		assertTrue("hitpoints must be gone when switched off: " + hidden,
			hidden.stream().noneMatch(l -> l.startsWith("Hitpoints|")));
		assertTrue("and the style skill must remain: " + hidden,
			hidden.stream().anyMatch(l -> l.matches("Strength\\|\\d+")));
	}

	@Test
	public void xpTargetIsNamedBesideTheSkill()
	{
		List<String> lines = new SimulatedGame()
			.xpTarget(VarPlayerID.XPDROPS_STRENGTH_END, 4470)   // level 20
			.kills(9)
			.renderedLines();

		assertTrue("the target level should be shown so the count is not misread: " + lines,
			lines.stream().anyMatch(l -> l.startsWith("Strength (20)|")));
	}

	@Test
	public void actuallyPutsPixelsOnScreen()
	{
		BufferedImage img = new SimulatedGame().kills(9).renderToImage();

		assertNotNull("the overlay rendered no image at all", img);
		assertTrue("overlay is implausibly small: " + img.getWidth() + "x" + img.getHeight(),
			img.getWidth() > 60 && img.getHeight() > 20);

		int drawn = 0;
		for (int y = 0; y < img.getHeight(); y++)
		{
			for (int x = 0; x < img.getWidth(); x++)
			{
				if ((img.getRGB(x, y) >>> 24) != 0)
				{
					drawn++;
				}
			}
		}
		assertTrue("overlay drew almost nothing: " + drawn + " opaque pixels", drawn > 500);
	}
}

package com.killstolevel;

import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;
import net.runelite.api.NPC;
import net.runelite.api.Skill;
import net.runelite.api.WorldType;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.NpcUtil;
import net.runelite.client.ui.overlay.OverlayManager;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Drives the plugin's real event handlers against a mocked client. The estimator's arithmetic is
 * covered by {@link KillXpEstimatorTest}; what is exercised here is the event plumbing around it —
 * which kills get credited, which tick a kill is priced at, and which skills a kill counts as
 * having trained.
 */
public class KillCreditTest
{
	/** Goblin: 5 hitpoints, so 5 damage and 4 XP per damage. */
	private static final int DAMAGE = 5;
	private static final int DESPAWN_LAG_TICKS = 6;   // measured in-client

	private final Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
	private Client client;
	private NpcUtil npcUtil;
	private KillsToLevelConfig config;
	private KillsToLevelPlugin plugin;
	private int nextNpcIndex;

	@Before
	public void setUp()
	{
		client = mock(Client.class);
		npcUtil = mock(NpcUtil.class);

		when(client.getSkillExperience(any(Skill.class)))
			.thenAnswer(inv -> xp.getOrDefault(inv.<Skill>getArgument(0), 0));

		config = mock(KillsToLevelConfig.class);
		when(config.sampleWindow()).thenReturn(20);
		when(config.useInGameGoal()).thenReturn(true);
		when(config.showHitpoints()).thenReturn(true);
		when(client.getVarpValue(anyInt())).thenReturn(0);   // no in-game target set
		when(client.getWorldType()).thenReturn(EnumSet.noneOf(WorldType.class));

		plugin = new KillsToLevelPlugin();
		plugin.client = client;
		plugin.npcUtil = npcUtil;
		plugin.config = config;
		plugin.overlayManager = mock(OverlayManager.class);
		plugin.overlay = mock(KillsToLevelOverlay.class);

		xp.put(Skill.STRENGTH, 1000);
		xp.put(Skill.HITPOINTS, 5000);
		xp.put(Skill.MAGIC, 3000);

		plugin.startUp();
	}

	private void tick()
	{
		plugin.onGameTick(new GameTick());
	}

	private void tick(int times)
	{
		for (int i = 0; i < times; i++)
		{
			tick();
		}
	}

	private NPC npc()
	{
		NPC npc = mock(NPC.class);
		when(npc.getIndex()).thenReturn(++nextNpcIndex);
		return npc;
	}

	private void grant(Skill skill, int amount)
	{
		xp.merge(skill, amount, Integer::sum);
	}

	/**
	 * A real {@link Hitsplat}, not a mock: {@code isMine()} is a default method on the interface, so
	 * only the hitsplat type is ours to supply and RuneLite's own classification is what runs. If
	 * RuneLite changes which types count as the player's, these tests follow it.
	 */
	private static Hitsplat hitsplat(int type, int amount)
	{
		return new Hitsplat()
		{
			@Override
			public int getHitsplatType()
			{
				return type;
			}

			@Override
			public int getAmount()
			{
				return amount;
			}

			@Override
			public int getDisappearsOnGameCycle()
			{
				return 0;
			}
		};
	}

	/** Land a hit, granting XP on the same tick — the client does exactly this. */
	private void hit(NPC npc, int damage, boolean mine)
	{
		hit(npc, damage, mine ? HitsplatID.DAMAGE_ME : HitsplatID.DAMAGE_OTHER);
	}

	private void hit(NPC npc, int damage, int hitsplatType)
	{
		Hitsplat hitsplat = hitsplat(hitsplatType, damage);
		if (hitsplat.isMine())
		{
			grantKillXp(damage);
		}
		applyHitsplat(npc, hitsplat);
	}

	/** Land our hit but withhold the XP, so a caller can deliver it on a later tick. */
	private void hitWithoutXp(NPC npc, int damage)
	{
		applyHitsplat(npc, hitsplat(HitsplatID.DAMAGE_ME, damage));
	}

	private void applyHitsplat(NPC npc, Hitsplat hitsplat)
	{
		HitsplatApplied event = new HitsplatApplied();
		event.setActor(npc);
		event.setHitsplat(hitsplat);
		plugin.onHitsplatApplied(event);
	}

	private void grantKillXp(int damage)
	{
		grant(Skill.STRENGTH, damage * 4);
		grant(Skill.HITPOINTS, (damage * 4) / 3);
	}

	private void grantDefenceKillXp(int damage)
	{
		grant(Skill.DEFENCE, damage * 4);
		grant(Skill.HITPOINTS, (damage * 4) / 3);
	}

	private void despawn(NPC npc, boolean dying)
	{
		when(npcUtil.isDying(npc)).thenReturn(dying);
		plugin.onNpcDespawned(new NpcDespawned(npc));
	}

	/** A whole kill: killing blow, then the corpse lingering before it despawns. */
	private void killOne()
	{
		killOne(DAMAGE);
	}

	/**
	 * A kill ordered the way the live client orders it: the client applies the damage and grants the
	 * XP, RuneLite posts GameTick, and only then posts HitsplatApplied for that same cycle. So the
	 * blow's XP is already in the tick that just closed, while lastHitTick names the tick that has
	 * just begun — measured in-client, every kill, without exception.
	 */
	private void killOne(int damage)
	{
		NPC goblin = npc();
		grantKillXp(damage);
		tick();
		applyHitsplat(goblin, hitsplat(HitsplatID.DAMAGE_ME, damage));
		tick(DESPAWN_LAG_TICKS - 1);
		despawn(goblin, true);
	}

	/** Mirrors {@link #killOne(int)} but trains Defence — for testing a switch between styles. */
	private void killOneTrainingDefence()
	{
		NPC goblin = npc();
		grantDefenceKillXp(DAMAGE);
		tick();
		applyHitsplat(goblin, hitsplat(HitsplatID.DAMAGE_ME, DAMAGE));
		tick(DESPAWN_LAG_TICKS - 1);
		despawn(goblin, true);
	}

	private void login()
	{
		GameStateChanged event = new GameStateChanged();
		event.setGameState(GameState.LOGGED_IN);
		plugin.onGameStateChanged(event);
	}

	private void configChanged(String group)
	{
		ConfigChanged event = new ConfigChanged();
		event.setGroup(group);
		plugin.onConfigChanged(event);
	}

	@Test
	public void fiveKillsProduceAnEstimateForTheTrainedSkill()
	{
		tick(2);   // settle the XP history before any kill
		for (int i = 0; i < 5; i++)
		{
			killOne();
		}

		// 5 snapshots -> 4 intervals of 20 xp -> 20 xp/kill. 1100 xp is level 9;
		// level 10 is 1154, so 54 remaining, ceil(54 / 20) = 3.
		assertEquals(1100, (int) xp.get(Skill.STRENGTH));
		assertEquals(3, plugin.killsToLevel(Skill.STRENGTH));
		assertTrue("a kill must mark the skill it trained", plugin.isRecentlyTrained(Skill.STRENGTH));
	}

	@Test
	public void skillNotTrainedByTheKillIsNotListed()
	{
		tick(2);
		for (int i = 0; i < 5; i++)
		{
			killOne();
			grant(Skill.MAGIC, 65);   // alching between kills, never on a killing blow
			tick();
		}

		assertTrue(plugin.isRecentlyTrained(Skill.STRENGTH));
		assertFalse("magic xp that never landed on a kill must not list magic",
			plugin.isRecentlyTrained(Skill.MAGIC));
	}

	@Test
	public void damageThatIsNotOursIsNotCredited()
	{
		tick(2);
		for (int i = 0; i < 5; i++)
		{
			NPC goblin = npc();
			hit(goblin, DAMAGE, false);   // cannon / thrall / another player
